254	  // Total: 95000 - 7006 + 18480 = 106474
255	  assert.equal(totals.subtotal, 95000);
256	  assert.equal(totals.discount, 7006);
257	  assert.equal(totals.vat, 18480);
258	  assert.equal(totals.total, 106474);
259	});
