test('invoiceTotals with single line discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });

  const totals = invoiceTotals(result.value);
  // subtotal = 95000
  // line discount = 95000 × 10 / 100 = 9500
  // bulk discount (qty >= 10) = (95000 - 9500) × 2.5 / 100 = 2138
  // total discount = 9500 + 2138 = 11638
  // taxable = 95000 - 11638 = 83362
  // VAT (21%) = 83362 × 21 / 100 = 17506
  // total = 95000 - 11638 + 17506 = 100868
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 11638);
  assert.equal(totals.vat, 17506);
  assert.equal(totals.total, 100868);
});

