test('invoiceTotals returns subtotal and total for single line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const totals = invoiceTotals(result.value);
  // C-001 is gold tier (5% discount): 95000 × 5 / 100 = 4750
  // Bulk discount (qty >= 10): (95000 - 4750) × 2.5 / 100 = 90250 × 2.5 / 100 = 2256.25 → 2256
  // Taxable: 95000 - 4750 - 2256 = 87994
  // VAT (21%): 87994 × 21 / 100 = 18479.74 → 18479
  // Total discount: 4750 + 2256 = 7006
  // Total: 95000 - 7006 + 18479 = 106473
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 7006);
  assert.equal(totals.vat, 18479);
  assert.equal(totals.total, 106473);
});

test('invoiceTotals sums multiple line items', () => {
  const result = createInvoice({
