test('invoiceTotals total is clamped at zero with large voucher', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const totals = invoiceTotals(invoiceResult.value);
  const largeVoucherAmount = totals.subtotal + totals.vat + 10000;

  const voucherResult = applyVoucher(invoiceResult.value, { code: 'BIGPROMO', amount: largeVoucherAmount });
  const newTotals = invoiceTotals(voucherResult.value);

  assert.equal(newTotals.total, 0);
  assert.equal(newTotals.voucher, largeVoucherAmount);
});

test('applyVoucher does not mutate original invoice', () => {
