  assert.equal(JSON.stringify(invoiceResult.value), original);
});

test('applyVoucher returns distinct objects', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result1 = applyVoucher(invoiceResult.value, { code: 'PROMO10', amount: 5000 });
  const result2 = applyVoucher(invoiceResult.value, { code: 'PROMO10', amount: 5000 });

  assert.notEqual(result1.value, result2.value);
  assert.deepEqual(result1.value, result2.value);
});

