test('invoiceTotals with tier discount applied', () => {
  // C-001 is gold tier (5%)
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const totals = invoiceTotals(result.value);
  // subtotal = 95000
  // tier discount = 95000 × 5 / 100 = 4750
  // bulk discount = (95000 - 4750) × 2.5 / 100 = 2256
  // total discount = 4750 + 2256 = 7006
  // taxable = 95000 - 7006 = 87994
  // VAT (21%) = 18479.74 → 18480 (banker's rounding)
  // total = 95000 - 7006 + 18480 = 106474
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 7006);
  assert.equal(totals.vat, 18480);
  assert.equal(totals.total, 106474);
});

