test('invoiceTotals returns subtotal and total for single line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const totals = invoiceTotals(result.value);
  // C-001 is gold tier (5% discount): 95000 × 5 / 100 = 4750
  // Bulk discount (qty >= 10): (95000 - 4750) × 2.5 / 100 = 90250 × 2.5 / 100 = 2256.25 → 2256
  // Taxable: 95000 - 4750 - 2256 = 87994
  // VAT (21%): 87994 × 21 / 100 = 18479.74 → 18479
  // Total discount: 4750 + 2256 = 7006
  // Total: 95000 - 7006 + 18479 = 106473
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 7006);
  assert.equal(totals.vat, 18479);
  assert.equal(totals.total, 106473);
});

test('invoiceTotals sums multiple line items', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  const totals = invoiceTotals(result.value);
  // Subtotal: 95000 + 42500 = 137500
  // DEV-HOUR: qty 10, line discount 5%: 4750, bulk discount: 2256, taxable: 87994, VAT: 18480
  // DES-HOUR: qty 5, line discount 5%: 2125, bulk discount: 0, taxable: 40375, VAT: 8479
  // Total discount: 4750 + 2125 + 2256 = 9131
  // Total VAT: 18480 + 8479 = 26959
  // Total: 137500 - 9131 + 26959 = 155328
  assert.equal(totals.subtotal, 137500);
  assert.equal(totals.discount, 9131);
  assert.equal(totals.vat, 26959);
  assert.equal(totals.total, 155328);
});

test('invoiceTotals sums complex line items', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 8 },
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'ICON-SET', qty: 2 },
      { sku: 'STICKER', qty: 50 },
    ],
  });

  const totals = invoiceTotals(result.value);
  // Subtotal: 105960
  // Line discounts (5% tier): 3800 + 1275 + 98 + 125 = 5298
  // Bulk discounts (only STICKER qty 50): 59
  // Total discount: 5357
  // DEV-HOUR: 76000, line disc 3800, no bulk, taxable 72200, VAT: 15162
  // DES-HOUR: 25500, line disc 1275, no bulk, taxable 24225, VAT: 5087
  // ICON-SET: 1960, line disc 98, no bulk, taxable 1862, VAT: 391
  // STICKER: 2500, line disc 125, bulk 59, taxable 2316, VAT: 486
  // Total VAT: 21126, Total: 105960 - 5357 + 21126 = 121729
  assert.equal(totals.subtotal, 105960);
  assert.equal(totals.discount, 5357);
  assert.equal(totals.vat, 21126);
  assert.equal(totals.total, 121729);
});

