    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const totals = invoiceTotals(invoiceResult.value);
  const largeVoucherAmount = totals.subtotal + totals.vat + 10000;

  const voucherResult = applyVoucher(invoiceResult.value, { code: 'BIGPROMO', amount: largeVoucherAmount });
  const newTotals = invoiceTotals(voucherResult.value);

  assert.equal(newTotals.total, 0);
  assert.equal(newTotals.voucher, largeVoucherAmount);
});

test('applyVoucher does not mutate original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const original = JSON.stringify(invoiceResult.value);
  applyVoucher(invoiceResult.value, { code: 'PROMO10', amount: 5000 });
  assert.equal(JSON.stringify(invoiceResult.value), original);
});

test('applyVoucher returns distinct objects', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result1 = applyVoucher(invoiceResult.value, { code: 'PROMO10', amount: 5000 });
  const result2 = applyVoucher(invoiceResult.value, { code: 'PROMO10', amount: 5000 });

  assert.notEqual(result1.value, result2.value);
  assert.deepEqual(result1.value, result2.value);
});

test('invoiceTotals with voucher and discounts', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });

  const voucherResult = applyVoucher(invoiceResult.value, { code: 'PROMO10', amount: 5000 });
  const totals = invoiceTotals(voucherResult.value);

  assert(totals.discount > 0);
  assert.equal(totals.voucher, 5000);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat - 5000);
});

