test('lineVAT calculates VAT correctly', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
  };

  // lineTotal = 10 × 9500 = 95000
  // bulk discount (qty >= 10) = 95000 × 2.5 / 100 = 2375
  // VAT on (95000 - 2375) = 92625 × 21 / 100 = 19451.25 → 19451
  assert.equal(lineVAT(line), 19451);
});

