test('createInvoice rejects invalid terms', () => {
  const invalidTerms = ['NET15', 'NET60', 'IMMEDIATE', 'INVALID', ''];

  for (const invalidTerm of invalidTerms) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: 5 }],
      terms: invalidTerm,
    });
    assert.deepEqual(result, { ok: false, error: 'TERMS_INVALID' }, `Failed for term: "${invalidTerm}"`);
  }
});

test('createInvoice EOM with different months', () => {
  const testCases = [
    { issueDate: '2025-01-15', expectedDue: '2025-01-31' },
    { issueDate: '2025-02-15', expectedDue: '2025-02-28' },
    { issueDate: '2025-04-15', expectedDue: '2025-04-30' },
    { issueDate: '2025-12-15', expectedDue: '2025-12-31' },
  ];

  for (const { issueDate, expectedDue } of testCases) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate,
      lines: [{ sku: 'DEV-HOUR', qty: 5 }],
      terms: 'EOM',
    });
    assert.equal(result.ok, true, `Failed for date: ${issueDate}`);
    assert.equal(result.value.dueDate, expectedDue, `Wrong due date for: ${issueDate}`);
  }
});

