test('applyVoucher rejects non-draft invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const result = applyVoucher(issuedResult.value, { code: 'PROMO10', amount: 5000 });
  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

